do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();r1 uuid:=gen_random_uuid();r2 uuid:=gen_random_uuid();req uuid:=gen_random_uuid();w text;cat text:='category-test-'||left(a::text,8);movement text:='rm-test-'||left(a::text,8);v jsonb;denied boolean;photo uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email,raw_user_meta_data) select x,x::text||'@example.invalid',jsonb_build_object('full_name','검증 회원','privacy_consent',true,'privacy_version','privacy-2026-11-04','age_over_14',true,'disclosure_consent',true) from unnest(array[a,b,c])x;
 update public.gym_members set role='admin',status='approved' where id=a;update public.gym_members set status='approved' where id in(b,c);
 insert into auth.users(id,email,raw_user_meta_data) values(d,d::text||'@example.invalid','{"full_name":"대기 회원","privacy_consent":true}');
 denied:=false;begin update public.gym_members set status='approved' where id=d;exception when check_violation then denied:=true;end;if not denied then raise exception 'unconfirmed age approved';end if;
 perform public.onoff_privacy_accept(d,'{"version":"privacy-2026-11-04","ageOver14":true,"disclosure":false}');update public.gym_members set status='approved' where id=d;
 if (select disclosure_consent from public.gym_members where id=d) then raise exception 'optional disclosure forced';end if;
 if (select count(*) from public.gym_named_wods)<>54 or (select count(*) from public.gym_named_wods where is_default)<>10 then raise exception 'catalogue seed wrong';end if;
 perform public.onoff_named_mutate(a,jsonb_build_object('action','category','label',cat));select id into cat from public.gym_named_categories where label=cat;
 v:=public.onoff_named_mutate(a,jsonb_build_object('action','catalogue','name','Verification WOD '||left(a::text,8),'description','For time: 10 Burpees','categoryId',cat,'recordType','time','isDefault',true,'active',true));w:=v->>'id';
 perform public.onoff_named_mutate(b,jsonb_build_object('action','record','id',r1,'wodId',w,'date',(now() at time zone 'Asia/Seoul')::date,'seconds',123,'note','first'));
 perform public.onoff_named_mutate(b,jsonb_build_object('action','record','id',r2,'wodId',w,'date',(now() at time zone 'Asia/Seoul')::date,'seconds',100,'note','best'));
 if (select min(seconds) from public.gym_named_records where user_id=b)<>100 then raise exception 'time best wrong';end if;
 denied:=false;begin perform public.onoff_named_mutate(c,jsonb_build_object('action','record-delete','id',r1));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'cross-member record deletion';end if;
 denied:=false;begin perform public.onoff_named_mutate(b,jsonb_build_object('action','catalogue-delete','id',w));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'member managed catalogue';end if;
 perform public.onoff_named_mutate(b,jsonb_build_object('action','record','id',r2,'wodId',w,'date',(now() at time zone 'Asia/Seoul')::date,'seconds',150,'note','corrected'));
 if (select min(seconds) from public.gym_named_records where user_id=b)<>123 then raise exception 'best after edit wrong';end if;
 perform public.onoff_named_mutate(b,jsonb_build_object('action','record-delete','id',r1));if (select min(seconds) from public.gym_named_records where user_id=b)<>150 then raise exception 'best after delete wrong';end if;
 perform public.onoff_named_mutate(a,jsonb_build_object('action','category-delete','id',cat,'targetId','mixed'));
 if (select category_id from public.gym_named_wods where id=w)<>'mixed' then raise exception 'category move lost records';end if;
 perform public.onoff_named_mutate(a,jsonb_build_object('action','catalogue-delete','id',w));if not exists(select 1 from public.gym_named_records where id=r2) then raise exception 'catalogue delete removed history';end if;
 v:=public.onoff_named_snapshot(c);if jsonb_array_length(v->'records')<>0 then raise exception 'named snapshot leaked other records';end if;
 update public.gym_settings set value=value||jsonb_build_array(jsonb_build_object('id',movement,'name',movement,'category','squat','active',true,'isDefault',false,'aliases','[]'::jsonb)) where key='rmCatalogue';
 insert into public.gym_rms(id,user_id,body) values(gen_random_uuid(),b,jsonb_build_object('movementId',movement,'lbs',100)),(gen_random_uuid(),b,jsonb_build_object('movementId',movement,'lbs',200)),(gen_random_uuid(),c,jsonb_build_object('movementId',movement,'lbs',200)),(gen_random_uuid(),d,jsonb_build_object('movementId',movement,'lbs',300));
 v:=public.onoff_rm_comparison(b,movement);if (v->>'total')::int<>2 or (v->>'equal')::int<>2 or (v->>'ownBest')::numeric<>200 or v ? 'names' then raise exception 'RM dedup/tie/privacy wrong: %',v;end if;
 insert into public.gym_photos(id,owner_id,kind,path,uploaded,active) values(photo,b,'daily',b::text||'/'||photo::text||'.jpg',true,true);
 insert into public.gym_point_accounts(user_id,balance) values(b,33) on conflict(user_id) do update set balance=33;
 insert into public.gym_point_coupons(user_id,name,price,total,remaining,request_id) values(b,'검증 쿠폰',10,1,1,gen_random_uuid());
 denied:=false;begin perform public.onoff_account_delete_prepare(c,b,req,'검증 회원');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'member deleted account';end if;
 v:=public.onoff_account_delete_prepare(a,b,req,'검증 회원');if jsonb_array_length(v->'paths')<>1 then raise exception 'photo deletion paths missing';end if;
 denied:=false;begin update public.gym_members set status='approved' where id=b;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'deletion account reapproved';end if;
 delete from auth.users where id=b;
 if not exists(select 1 from public.gym_account_deletions where id=req and completed_at is not null) then raise exception 'deletion audit not completed by cascade';end if;
 perform public.onoff_account_delete_complete(a,b,req);
 if exists(select 1 from public.gym_point_accounts where user_id=b) or exists(select 1 from public.gym_point_coupons where user_id=b) or exists(select 1 from public.gym_named_records where user_id=b) or exists(select 1 from public.gym_photos where id=photo) then raise exception 'account cascade retained private data/points/coupons';end if;
 if not exists(select 1 from public.gym_photo_cleanup where path=b::text||'/'||photo::text||'.jpg') then raise exception 'photo cleanup not durable';end if;
 v:=public.onoff_account_delete_prepare(a,b,req,'검증 회원');if v->>'already'<>'true' then raise exception 'delete retry not idempotent';end if;
 perform set_config('onoff.test_auth_delete',c::text,true);
end $test$;
select true as batch7_passed,not has_table_privilege('anon','public.gym_named_records','select') as records_private,not has_function_privilege('authenticated','public.onoff_named_mutate(uuid,jsonb)','execute') as mutations_private;
